-- ----------------------------
-- Table structure for client_user
-- ----------------------------
DROP TABLE IF EXISTS `client_user`;
CREATE TABLE `client_user`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `AVATAR` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '头像',
  `REMARK` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ACCOUNT` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账号',
  `PASSWORD` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '密码',
  `NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '姓名',
  `CUSTOMER_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编号（系统自动生成，唯一；C端注册用户为空）',
  `NICKNAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '昵称',
  `GENDER` tinyint NULL DEFAULT NULL COMMENT '性别（0-未知 1-男 2-女）',
  `AGE` int NULL DEFAULT NULL COMMENT '年龄',
  `BIRTHDAY` date NULL DEFAULT NULL COMMENT '出生日期',
  `PHONE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机',
  `WECHAT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信号',
  `EMAIL` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `OCCUPATION` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职业',
  `PROVINCE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省份',
  `CITY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市',
  `DISTRICT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区县',
  `PROVINCE_ID` int NULL DEFAULT NULL COMMENT '省地区ID（关联sys_system_city.city_id）',
  `CITY_ID` int NULL DEFAULT NULL COMMENT '市地区ID（关联sys_system_city.city_id）',
  `DISTRICT_ID` int NULL DEFAULT NULL COMMENT '区县地区ID（关联sys_system_city.city_id）',
  `ADDRESS` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `CUSTOMER_SOURCE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户来源（字典CRM_CUSTOMER_SOURCE）',
  `CUSTOMER_TYPE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户类型（NORMAL-普通客户 LEAD-线索 INTENTION-意向 DEAL-成交 OLD-老客 SLEEP-沉睡；C端注册用户为空，由CRM建档驱动流转）',
  `LEVEL_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户等级ID（关联crm_customer_level）',
  `ANNIVERSARY` date NULL DEFAULT NULL COMMENT '结婚纪念日',
  `CHILD_BIRTHDAY` date NULL DEFAULT NULL COMMENT '儿童生日',
  `TOTAL_AMOUNT` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '累计消费金额',
  `TOTAL_COUNT` int NOT NULL DEFAULT 0 COMMENT '累计消费次数',
  `LAST_DEAL_TIME` datetime NULL DEFAULT NULL COMMENT '最近成交时间',
  `LAST_FOLLOW_TIME` datetime NULL DEFAULT NULL COMMENT '最近跟进时间',
  `NEXT_FOLLOW_TIME` datetime NULL DEFAULT NULL COMMENT '下次跟进计划时间',
  `INTENTION_LEVEL` tinyint NULL DEFAULT NULL COMMENT '意向程度（1-低 2-中 3-高）',
  `BELONG_USER_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '归属员工ID（关联sys_user）',
  `BELONG_STORE_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '归属门店ID（关联sys_org）',
  `MEMBER_BALANCE` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '会员储值余额',
  `MEMBER_POINTS` int NOT NULL DEFAULT 0 COMMENT '会员积分',
  `IS_BLACKLIST` tinyint NOT NULL DEFAULT 0 COMMENT '是否黑名单（0-否 1-是）',
  `USER_STATUS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户状态',
  `SORT_CODE` int NULL DEFAULT NULL COMMENT '排序码',
  `DELETE_FLAG` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '删除标志',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  `EXT_JSON` json NULL COMMENT '行业扩展字段（key=field_code）',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uk_customer_no`(`DELETE_FLAG` ASC, `CUSTOMER_NO` ASC) USING BTREE,
  INDEX `idx_wechat`(`WECHAT` ASC) USING BTREE,
  INDEX `idx_customer_type`(`CUSTOMER_TYPE` ASC) USING BTREE,
  INDEX `idx_level_id`(`LEVEL_ID` ASC) USING BTREE,
  INDEX `idx_belong_user`(`BELONG_USER_ID` ASC) USING BTREE,
  INDEX `idx_belong_store`(`BELONG_STORE_ID` ASC) USING BTREE,
  INDEX `idx_source`(`CUSTOMER_SOURCE` ASC) USING BTREE,
  INDEX `idx_next_follow`(`NEXT_FOLLOW_TIME` ASC) USING BTREE,
  INDEX `idx_create_time`(`CREATE_TIME` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户主表（原C端用户，与CRM客户档案合并）' ROW_FORMAT = DYNAMIC;

